'use client';
import { useEffect, useId, useRef, useState, type KeyboardEvent, type PointerEvent, type ReactNode } from 'react';
import { cssEase, duration as D, useIsomorphicLayoutEffect, useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import styles from './styles.module.css';

type Params = { duration: number; slides: number; transition: string; autoAdvance: boolean };
type Tone = 'signal' | 'ink' | 'tint' | 'paper';

/** Sample content: a fictional field-notes story, drawn with type and CSS only. */
const SLIDES: readonly { tone: Tone; body: ReactNode }[] = [
  {
    tone: 'signal',
    body: (
      <>
        <span className={styles.sun} aria-hidden="true" />
        <span className={styles.horizon} aria-hidden="true" />
        <p className={styles.eyebrow}>Field notes · No. 14</p>
        <p className={styles.hero}>Low tide, 06:40</p>
        <p className={styles.small}>A morning on the flats</p>
      </>
    ),
  },
  {
    tone: 'ink',
    body: (
      <>
        <p className={styles.giant}>40</p>
        <p className={styles.lede}>minutes before the water turns around and comes back for the sand.</p>
      </>
    ),
  },
  {
    tone: 'tint',
    body: (
      <>
        <p className={styles.quote}>“The sea had left its handwriting everywhere.”</p>
        <p className={styles.small}>Notebook, page 3</p>
      </>
    ),
  },
  {
    tone: 'paper',
    body: (
      <>
        <p className={styles.eyebrow}>Found on the walk</p>
        <ol className={styles.list}>
          <li>Razor shells, by the dozen</li>
          <li>A blue rope, knotted twice</li>
          <li>One boot (left)</li>
        </ol>
      </>
    ),
  },
  {
    tone: 'signal',
    body: (
      <>
        <svg className={styles.route} viewBox="0 0 100 100" aria-hidden="true" focusable="false">
          <path d="M14 86 C 30 70, 22 52, 44 46 S 70 30, 84 14" />
          <circle cx="14" cy="86" r="3.5" />
          <circle cx="84" cy="14" r="3.5" />
        </svg>
        <p className={styles.eyebrow}>The route</p>
        <p className={styles.hero}>Sea wall to the channel marker</p>
      </>
    ),
  },
  {
    tone: 'ink',
    body: (
      <>
        <p className={styles.eyebrow}>Next low tide</p>
        <p className={styles.hero}>19:12</p>
        <p className={styles.small}>See you out there.</p>
      </>
    ),
  },
];

const TAP_MS = 250; // shorter presses are taps (navigate); longer ones were holds (pause only)

export default function StoryProgressSegments({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const count = Math.max(3, Math.min(SLIDES.length, Math.round(params.slides)));
  const auto = params.autoAdvance && !reduced;
  const [index, setIndex] = useState(0);
  const [restart, setRestart] = useState(0);
  const [paused, setPaused] = useState(false);
  const [holding, setHolding] = useState(false);
  const [ended, setEnded] = useState(false);
  const segFills = useRef<(HTMLSpanElement | null)[]>([]);
  const slideEls = useRef<(HTMLDivElement | null)[]>([]);
  const segAnim = useRef<Animation | null>(null);
  const shown = useRef(0);
  const hold = useRef<{ t: number; x: number; w: number } | null>(null);
  const current = Math.min(index, count - 1);
  const playing = auto && !paused && !holding && !ended;

  const next = () => { if (current + 1 >= count) setEnded(true); else { setEnded(false); setIndex(current + 1); } };
  const prev = () => { setEnded(false); if (current === 0) setRestart((r) => r + 1); else setIndex(current - 1); };
  const toggle = () => {
    if (ended) { setEnded(false); setPaused(false); setIndex(0); setRestart((r) => r + 1); return; }
    setPaused((p) => !p);
  };

  // The current segment's fill is the clock: its finish advances the story.
  useIsomorphicLayoutEffect(() => {
    segAnim.current = null;
    const el = segFills.current[current];
    if (!auto || ended || !el || typeof el.animate !== 'function') return;
    const a = el.animate([{ transform: 'scaleX(0)' }, { transform: 'scaleX(1)' }], { duration: params.duration, easing: 'linear', fill: 'forwards' });
    segAnim.current = a;
    a.onfinish = () => {
      if (segAnim.current !== a) return;
      if (current + 1 >= count) setEnded(true);
      else setIndex(current + 1);
    };
    return () => { a.onfinish = null; a.cancel(); };
  }, [current, auto, ended, count, params.duration, restart]);

  // Pause / hold / resume without restarting the segment.
  useEffect(() => {
    const a = segAnim.current;
    if (!a) return;
    if (paused || holding) a.pause();
    else if (a.playState === 'paused') a.play();
  }, [paused, holding, current, restart, auto, ended]);

  // Slide change: a short push or fade between the outgoing and incoming slide.
  useIsomorphicLayoutEffect(() => {
    const from = shown.current;
    shown.current = current;
    if (from === current) return;
    const inEl = slideEls.current[current];
    const outEl = slideEls.current[from];
    const dir = current > from ? 1 : -1;
    const mode = reduced ? 'fade' : params.transition;
    if (mode === 'none') return;
    const ms = reduced ? 160 : mode === 'fade' ? D.base : D.moderate;
    const ease = reduced ? 'linear' : cssEase('emphasized');
    const dx = mode === 'slide' ? 14 : 0;
    const list: Animation[] = [];
    if (inEl) list.push(inEl.animate([{ opacity: 0, transform: `translateX(${dir * dx}%)` }, { opacity: 1, transform: 'translateX(0)' }], { duration: ms, easing: ease }));
    if (outEl) list.push(outEl.animate([{ opacity: 1, visibility: 'visible', transform: 'translateX(0)' }, { opacity: 0, visibility: 'visible', transform: `translateX(${-dir * dx}%)` }], { duration: ms, easing: ease }));
    return () => { for (const a of list) a.cancel(); };
  }, [current]);

  // Tap zones (left 30 % back, rest forward) and press-and-hold to pause.
  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return;
    const r = e.currentTarget.getBoundingClientRect();
    hold.current = { t: performance.now(), x: e.clientX - r.left, w: r.width };
    if (auto && !ended) setHolding(true);
  };
  const endHold = (tap: boolean) => {
    const h = hold.current;
    if (!h) return;
    hold.current = null;
    setHolding(false);
    if (tap && performance.now() - h.t < TAP_MS) { if (h.x < h.w * 0.3) prev(); else next(); }
  };

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'ArrowRight') { e.preventDefault(); next(); }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); prev(); }
    else if (e.key === ' ' && !(e.target as HTMLElement).closest('button') && auto) { e.preventDefault(); toggle(); }
  };

  const tone = SLIDES[current].tone;
  const position = `Slide ${current + 1} of ${count}`;
  const state = ended ? 'end of story' : !auto ? (reduced ? 'auto-advance off (reduced motion)' : 'auto-advance off') : paused ? 'paused' : holding ? 'held' : 'playing';

  return (
    <div className={styles.root} data-reduced={reduced || undefined} onKeyDown={onKeyDown}>
      <section
        className={styles.frame}
        data-tone={tone}
        data-manual={!auto || undefined}
        tabIndex={0}
        aria-label="Story: Tidewater Notes (sample content)"
        aria-describedby={`${uid}help`}
      >
        <div className={styles.slides} aria-live={playing ? 'off' : 'polite'}>
          {SLIDES.slice(0, count).map((s, i) => (
            <div
              key={i}
              ref={(el) => { slideEls.current[i] = el; }}
              className={styles.slide}
              data-tone={s.tone}
              data-current={i === current || undefined}
              role="group"
              aria-roledescription="slide"
              aria-label={`${i + 1} of ${count}`}
              inert={i !== current}
            >
              {s.body}
            </div>
          ))}
        </div>

        <div className={styles.overlay} aria-hidden="true">
          <div className={styles.segments}>
            {Array.from({ length: count }, (_, i) => (
              <span key={i} className={styles.seg} data-state={ended || i < current ? 'done' : i === current ? 'current' : 'next'}>
                <span ref={(el) => { segFills.current[i] = el; }} className={styles.segFill} />
              </span>
            ))}
          </div>
          <div className={styles.byline}>
            <span className={styles.avatar}>TN</span>
            <span className={styles.who}>Tidewater Notes</span>
            {auto && (paused || holding) && !ended ? <span className={styles.pill}>Paused</span> : null}
          </div>
        </div>

        {/* Tap zones: pointer-only duplicates of Previous / Next (and press-and-hold to pause). */}
        <div
          className={styles.zones}
          aria-hidden="true"
          onPointerDown={onPointerDown}
          onPointerUp={() => endHold(true)}
          onPointerCancel={() => endHold(false)}
          onPointerLeave={() => endHold(false)}
          onContextMenu={(e) => e.preventDefault()}
        >
          <span className={styles.chev} data-side="prev">‹</span>
          <span className={styles.chev} data-side="next">›</span>
        </div>
      </section>

      <div className={styles.controls}>
        <button type="button" className={styles.ctrl} onClick={prev}>
          <span aria-hidden="true">‹</span> Previous
        </button>
        {auto ? (
          <button type="button" className={styles.ctrl} data-primary="" onClick={toggle}>
            <span aria-hidden="true">{ended ? '↺' : paused ? '▶' : '❚❚'}</span> {ended ? 'Replay' : paused ? 'Play' : 'Pause'}
          </button>
        ) : null}
        <button type="button" className={styles.ctrl} onClick={next}>
          Next <span aria-hidden="true">›</span>
        </button>
      </div>
      <p className={styles.status}><span>{position}</span><span>{state}</span></p>
      <p id={`${uid}help`} className={styles.help}>
        {auto ? '← → move · Space pauses · tap the left third to go back · press and hold to pause' : '← → move · tap the left third to go back, the rest to go forward'}
      </p>
    </div>
  );
}

.root {
  box-sizing: border-box;
  width: min(100% - 2rem, 22rem);
  margin: clamp(1rem, 4cqi, 2rem) auto;
  display: grid;
  justify-items: center;
  gap: 0.875rem;
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
}

/* ── Frame ────────────────────────────────────────────────────────────── */
.frame {
  position: relative;
  container-type: inline-size;
  width: min(100%, 19rem);
  aspect-ratio: 9 / 16;
  overflow: hidden;
  border-radius: 22px;
  box-shadow: 0 0 0 1px var(--mk-line, #11110f24), 0 18px 40px -24px rgb(0 0 0 / 0.45);
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  touch-action: manipulation;
}
.frame:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 4px; }
.slides { display: grid; height: 100%; }

.slide {
  grid-area: 1 / 1;
  position: relative;
  display: grid;
  align-content: end;
  gap: 0.75rem;
  padding: 5.25rem 1.5rem 1.75rem;
  overflow: hidden;
  visibility: hidden;
}
.slide[data-current] { visibility: visible; }
.slide[data-tone='signal'] { background: var(--mk-signal, #bf2f09); color: var(--mk-on-signal, #ffffff); }
.slide[data-tone='ink'] { background: var(--mk-ink, #11110f); color: var(--mk-surface, #fbf9f4); }
.slide[data-tone='tint'] { background: var(--mk-surface-2, #e9e5da); color: var(--mk-ink, #11110f); }
.slide[data-tone='paper'] { background: var(--mk-surface, #fbf9f4); color: var(--mk-ink, #11110f); }
.frame[data-tone='signal'] .overlay { color: var(--mk-on-signal, #ffffff); }
.frame[data-tone='ink'] .overlay { color: var(--mk-surface, #fbf9f4); }
.frame[data-tone='tint'] .overlay, .frame[data-tone='paper'] .overlay { color: var(--mk-ink, #11110f); }

/* Typography (sized to the frame, not the page) */
.eyebrow, .small {
  margin: 0;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: max(0.6875rem, 4cqi);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.small { text-transform: none; letter-spacing: 0.02em; }
.hero {
  margin: 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: 15cqi;
  font-weight: 700;
  line-height: 0.92;
  letter-spacing: -0.04em;
  text-wrap: balance;
}
.giant {
  margin: 0 0 -0.04em;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: 52cqi;
  font-weight: 700;
  line-height: 0.8;
  letter-spacing: -0.06em;
}
.lede { margin: 0; font-size: max(1rem, 6.4cqi); line-height: 1.25; text-wrap: pretty; }
.quote {
  margin: 0;
  font-family: var(--mk-font-serif, Georgia, serif);
  font-size: 11cqi;
  font-style: italic;
  line-height: 1.04;
  letter-spacing: -0.01em;
  text-wrap: balance;
}
.list { display: grid; gap: 0.5rem; margin: 0; padding: 0; list-style: none; counter-reset: item; }
.list li {
  counter-increment: item;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.75rem;
  padding-top: 0.5rem;
  border-top: 1px solid currentColor;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: max(1rem, 7cqi);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.list li::before { content: counter(item, decimal-leading-zero); font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.55em; font-weight: 400; padding-top: 0.3em; }

/* CSS-drawn imagery */
.sun { position: absolute; top: 24%; right: 14%; width: 30cqi; aspect-ratio: 1; border-radius: 50%; background: currentColor; }
.horizon { position: absolute; left: 0; right: 0; top: calc(24% + 15cqi); height: 1px; background: currentColor; }
.route { position: absolute; inset: 18% 10% auto; width: 80%; height: auto; overflow: visible; }
.route path { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-dasharray: 0.1 4; }
.route circle { fill: currentColor; }

/* ── Overlay: segments + byline, coloured like the current slide ───────── */
.overlay { position: absolute; inset: 0 0 auto; z-index: 2; display: grid; gap: 0.75rem; padding: 0.875rem 0.875rem 0; pointer-events: none; }
.segments { display: flex; gap: 4px; }
.seg { flex: 1; height: 3px; overflow: hidden; border-radius: 2px; background: color-mix(in oklab, currentColor 34%, transparent); }
.segFill { display: block; height: 100%; background: currentColor; transform: scaleX(0); transform-origin: 0 50%; }
.seg[data-state='done'] .segFill,
.frame[data-manual] .seg[data-state='current'] .segFill { transform: scaleX(1); }
.byline { display: flex; align-items: center; gap: 0.5rem; font-size: 0.8125rem; font-weight: 600; }
.avatar {
  display: grid;
  place-items: center;
  width: 1.75rem;
  height: 1.75rem;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.625rem;
  letter-spacing: 0.04em;
}
.pill {
  margin-left: auto;
  padding: 0.125rem 0.5rem;
  border: 1px solid currentColor;
  border-radius: 999px;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.625rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* Tap zones (pointer only; the buttons below are the accessible path) */
.zones { position: absolute; inset: 0; z-index: 1; cursor: pointer; }
.chev {
  position: absolute;
  top: 50%;
  translate: 0 -50%;
  font-size: 2rem;
  line-height: 1;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--mk-duration-fast, 160ms) linear;
}
.frame[data-tone='signal'] .chev { color: var(--mk-on-signal, #ffffff); }
.frame[data-tone='ink'] .chev { color: var(--mk-surface, #fbf9f4); }
.chev[data-side='prev'] { left: 0.5rem; }
.chev[data-side='next'] { right: 0.5rem; }
@media (hover: hover) { .frame:hover .chev { opacity: 0.85; } }

/* ── Controls ─────────────────────────────────────────────────────────── */
.controls { display: flex; flex-wrap: wrap; justify-content: center; gap: 0.5rem; }
.ctrl {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  min-height: 2.75rem;
  padding: 0 1rem;
  border: 1px solid var(--mk-line-strong, #11110f);
  border-radius: 999px;
  background: transparent;
  color: var(--mk-ink, #11110f);
  font: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
}
.ctrl[data-primary] { min-width: 6.5rem; justify-content: center; background: var(--mk-ink, #11110f); color: var(--mk-surface, #fbf9f4); }
.ctrl span { font-size: 1.05em; line-height: 1; }
.ctrl:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
@media (hover: hover) { .ctrl:not([data-primary]):hover { background: var(--mk-surface-2, #e9e5da); } }
.status, .help {
  margin: 0;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  color: var(--mk-ink-muted, #5c5a52);
  text-align: center;
}
.status { display: flex; gap: 0.75rem; text-transform: uppercase; letter-spacing: 0.08em; }
.help { max-width: 34ch; line-height: 1.5; }
.root[data-reduced] .chev { transition: none; }
